import ast
import sys
import os

def build_cfg(source_code):
    if not isinstance(source_code, str):
        raise TypeError("Input must be a string")

    try:
        tree = ast.parse(source_code)
    except SyntaxError as e:
        raise ValueError(f"Invalid Python syntax: {e}")

    if not isinstance(tree, ast.Module):
        raise ValueError("Input must be a valid Python module")

    nodes = {}
    edges = []
    node_counter = 0
    entry_point = None
    exit_points = []

    def get_node_id(node):
        nonlocal node_counter
        node_id = f"node_{node_counter}"
        node_counter += 1
        return node_id

    def analyze_node(node, parent_id=None):
        node_id = get_node_id(node)
        nodes[node_id] = {
            "type": type(node).__name__,
            "line": getattr(node, 'lineno', None),
            "col": getattr(node, 'col_offset', None),
            "children": []
        }

        if parent_id:
            edges.append({"from": parent_id, "to": node_id})
            nodes[parent_id]["children"].append(node_id)

        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            nonlocal entry_point
            if entry_point is None:
                entry_point = node_id
            for child in ast.iter_child_nodes(node):
                analyze_node(child, node_id)
        elif isinstance(node, ast.Return):
            exit_points.append(node_id)
        elif isinstance(node, (ast.If, ast.For, ast.While, ast.Try, ast.With)):
            for child in ast.iter_child_nodes(node):
                analyze_node(child, node_id)
        elif isinstance(node, ast.ExceptHandler):
            for child in ast.iter_child_nodes(node):
                analyze_node(child, node_id)
        elif isinstance(node, ast.Break):
            exit_points.append(node_id)
        elif isinstance(node, ast.Continue):
            exit_points.append(node_id)
        else:
            for child in ast.iter_child_nodes(node):
                analyze_node(child, node_id)

    analyze_node(tree)

    if not entry_point:
        entry_point = list(nodes.keys())[0] if nodes else None

    return {
        "entry_point": entry_point,
        "exit_points": exit_points,
        "nodes": nodes,
        "edges": edges
    }

if __name__ == "__main__":
    try:
        source = sys.stdin.read()
        result = build_cfg(source)
        print(result)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)
